```bash
cd /home/vscode/nullness-benchmarks/libgdx && sed -i '70,75c\	  public Pixmap consumePixmap() {
	    if (!isPrepared) throw new GdxRuntimeException("Call prepare() before calling getPixmap()");
	    if (this.pixmap == null) throw new GdxRuntimeException("Pixmap is not available");
	    isPrepared = false;
	    Pixmap pixmap = this.pixmap;
	    this.pixmap = null;
	    return pixmap;
	  }' gdx/src/com/badlogic/gdx/graphics/glutils/FileTextureData.java && ./gradlew gdx:compileJava -x test -q > new_build_output.log 2>&1 && (grep -n "FileTextureData.java" new_build_output.log || echo "No FileTextureData errors") && grep -n "NullAway:.*errors" new_build_output.log || tail -n 40 new_build_output.log
